-- ---------------------------------------------------------------------------
-- FLAT HOUSE Z15A1 (Block Z15A1, 37 Units) unit-rate lists
-- (from '1-BoQ Flat House 4.20mx18.00m ( Block Z15A1-37Units ).xlsx':
--  sheet 'COVER Z15A1'  -> Lump Sum Work list  (INDIRECT WORK rows 15-19, column F;
--                          the 6 DIRECT WORK house rows are not recorded)
--  6 house-type sheets  -> Material List (column H) + Labor List (column I);
--                          a description carrying more than one rate pair is kept
--                          as one entry per pair, qualified with its BOQ section)
--
-- 86 -> 82 entries per list: four workbook descriptions were written two or three
-- ways with identical rates and are merged into one entry, respelled:
--   'Marble for counter top, bathroom& Balcony'   -> '... bathroom & Balcony'
--   'Wood dood WD-01' / 'Woor door WD-01'        -> 'Wood door WD-01 (0.80m x 2.10m)'
--   'Woor door WD-02'                             -> 'Wood door WD-02 (0.90m x 2.10m)'
-- 'Mable for Stair' and 'Mable for Stair (black color)' are BOTH kept - (black
-- color) is a real specification, not a typo - and only the spelling is corrected.
--
-- Idempotent: each category is appended only if its category id is not already
-- present. Safe to re-run. Run in the Supabase SQL editor (or at the end of a
-- full supabase.sql re-run).
-- ---------------------------------------------------------------------------

-- Lump Sum Work list: new category 'Flat House Z15A1 · Lump Sum Work' (fhs_1)
update public.ledger
set state = jsonb_set(
  state,
  '{lumpSum}',
  COALESCE(state->'lumpSum', '[]'::jsonb) || '{"children": [{"children": [], "id": "fhs_1_1", "name": "Engineering & Management Fee", "price": 25000, "unit": "Ls"}, {"children": [], "id": "fhs_1_2", "name": "Site Preparation & Temporary Fence", "price": 16280, "unit": "Ls"}, {"children": [], "id": "fhs_1_3", "name": "Temporary Water Supply", "price": 7400, "unit": "Ls"}, {"children": [], "id": "fhs_1_4", "name": "Temporary Electricity Supply", "price": 29600, "unit": "Ls"}, {"children": [], "id": "fhs_1_5", "name": "Safety & HSE (Health, Safety, Environment)", "price": 75850, "unit": "Ls"}]}'::jsonb,
  true
)
where id = 1
  and not exists (
    select 1 from jsonb_array_elements(COALESCE(state->'lumpSum', '[]'::jsonb)) c
    where c->>'id' = 'fhs_1'
  );

